<?php
session_start();if(!isset($_SESSION['user_id'])){header('Location: index.php');exit;}require 'config.php';$assignments=$pdo->query('SELECT a.id,a.title,a.subject,a.due_date,u.name AS teacher_name FROM assignments a JOIN users u ON u.id=a.teacher_id ORDER BY a.due_date ASC')->fetchAll();$name=$_SESSION['name']??'Student';$role=$_SESSION['role']??'student';
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Dashboard</title><link rel="stylesheet" href="assets/style.css"></head><body><header class="topbar"><a class="wordmark" href="dashboard.php">Assignment Portal</a><div class="top-actions"><span class="role-chip"><?=htmlspecialchars(ucfirst($role))?></span><a href="logout.php">Log out</a></div></header><main class="container"><section class="welcome"><div><p class="eyebrow">YOUR WORKSPACE</p><h1>Welcome, <?=htmlspecialchars($name)?>!</h1><p class="muted">Here are the assignments currently available.</p></div><?php if($role==='teacher'):?><a class="button" href="create_assignment.php">+ New assignment</a><?php endif;?></section><section class="section-heading"><h2>Assignments</h2><span class="muted"><?=count($assignments)?> listed</span></section><div class="assignment-grid"><?php if(!$assignments):?><div class="empty-state"><div class="empty-icon">✓</div><h3>No assignments yet</h3><p class="muted">New assignments will appear here once a teacher adds them.</p></div><?php else:foreach($assignments as $a):?><article class="assignment-card"><div class="card-top"><span class="subject-tag"><?=htmlspecialchars($a['subject'])?></span><span class="small muted">#<?=(int)$a['id']?></span></div><h3><?=htmlspecialchars($a['title'])?></h3><p class="small muted">Created by <?=htmlspecialchars($a['teacher_name'])?></p><p class="due-date">Due: <?=htmlspecialchars($a['due_date'])?></p><?php if($role==='student'):?><a class="button full" href="submit_assignment.php?id=<?=(int)$a['id']?>">View / submit</a><?php endif;?></article><?php endforeach;endif;?></div></main></body></html>
